/**
 * Creates a Date object that handles years < 100 correctly.
 *
 * JavaScript's `new Date(year, month, day)` treats two-digit years (0-99)
 * as 1900-1999. This utility ensures the year is set correctly.
 *
 * @example
 * createYearSafeDate(50, 0, 1) // Jan 1, 0050 (not 1950)
 * createYearSafeDate(2025, 0, 15) // Jan 15, 2025
 */
export declare function createYearSafeDate(year: number, month: number, day: number): Date;
